from ledger.errors import StatementError, StatementRowError, UnknownFormatError


def test_statement_errors_inherit_statement_error():
    assert issubclass(UnknownFormatError, StatementError)
    assert issubclass(StatementRowError, StatementError)


def test_statement_row_error_exposes_line_no():
    err = StatementRowError("bad amount", line_no=7)
    assert err.line_no == 7
    assert str(err) == "line 7: bad amount"


def test_unknown_format_line_no_defaults_to_none():
    assert UnknownFormatError("empty file").line_no is None

