"""Импорт банковских выписок.

Поддерживаются три формата (определяются по заголовку):

    nova:        date,amount,description           (2026-03-01,-350.00,Кофейня)
    sfera:       Дата;Сумма;Описание               (01.03.2026;-350,00;Кофейня)
    sfera_split: Дата;Описание;Приход;Расход       (01.03.2026;Кофейня;;350,00)

Файл читается как UTF-8 (с BOM или без) либо cp1251.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from collections.abc import Callable
from dataclasses import dataclass, field, replace
from decimal import Decimal
from pathlib import Path

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

_ISO_DATE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_SFERA_DATE = re.compile(r"(\d{2})\.(\d{2})\.(\d{4})", re.ASCII)
# Без знака: тысячи через пробел или NBSP, запятая, не больше двух знаков после неё.
_SFERA_UNSIGNED_AMOUNT = re.compile(r"(\d{1,3}(?:[  ]\d{3})+|\d+)(,\d{1,2})?", re.ASCII)
_THOUSANDS_SEPARATORS = re.compile(r"[  ]")


@dataclass(frozen=True)
class RowError:
    """Строка выписки, которую не удалось разобрать.

    line_no — физическая строка, с которой начинается запись (заголовок — строка 1).
    raw — текст записи как в файле, без перевода строки в конце.
    """

    line_no: int
    message: str
    raw: str = ""


@dataclass(frozen=True)
class ImportResult:
    """Итог импорта.

    added + duplicates + len(errors) равно числу непустых строк данных в файле.
    transactions — добавленные транзакции по порядку файла; id назначает хранилище
    (при dry_run id равен None и хранилище не меняется).
    """

    format: str
    encoding: str
    added: int
    duplicates: int
    errors: tuple[RowError, ...]
    transactions: list[Transaction] = field(default_factory=list)


@dataclass(frozen=True)
class _Format:
    name: str
    delimiter: str
    # Имена обязательных колонок в виде strip().casefold().
    columns: tuple[str, ...]
    # Из значений колонок (ключи — из columns) получает дату, сумму и описание.
    parse: Callable[[dict[str, str]], tuple[dt.date, Decimal, str]]


@dataclass(frozen=True)
class _Header:
    format: _Format
    # Колонка из format.columns -> её индекс в строке.
    index: dict[str, int]
    # Число колонок в заголовке; лишние непустые ячейки сверх него — ошибка строки.
    width: int


