    parse=_parse_sfera_split,
)
_FORMATS = {fmt.name: fmt for fmt in (_NOVA, _SFERA, _SFERA_SPLIT)}


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    """Декодирует файл: UTF-8 (BOM снимается), иначе cp1251. Возвращает текст и кодировку."""
    raw = Path(path).read_bytes()
    try:
        return raw.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return raw.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("file is neither UTF-8 nor cp1251", line_no=None) from exc


def _is_blank(cells: list[str]) -> bool:
    return not any(cell.strip() for cell in cells)


def _match_header(text: str, fmt: _Format) -> _Header | None:
    """Проверяет первую непустую строку как заголовок формата fmt."""
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=fmt.delimiter)
    try:
        for cells in reader:
            if _is_blank(cells):
                continue
            names = [cell.strip().casefold() for cell in cells]
            if not all(col in names for col in fmt.columns):
                return None
            index = {col: names.index(col) for col in fmt.columns}
            return _Header(format=fmt, index=index, width=len(cells))
    except csv.Error:
        return None
    return None


def _detect(text: str, fmt_name: str | None) -> _Header:
    if fmt_name is not None and fmt_name not in _FORMATS:
        raise ValueError(f"unknown format {fmt_name!r}, expected one of {', '.join(_FORMATS)}")
    candidates = [_FORMATS[fmt_name]] if fmt_name is not None else list(_FORMATS.values())
    found = [h for h in (_match_header(text, fmt) for fmt in candidates) if h is not None]
    if len(found) == 1:
        return found[0]
    if not text.strip():
        raise UnknownFormatError("file is empty", line_no=None)
    if fmt_name is not None:
        message = f"header does not match format {fmt_name!r}"
    elif found:
        message = "header matches several formats: " + ", ".join(h.format.name for h in found)
    else:
        message = "unrecognized header"
    raise UnknownFormatError(message, line_no=1)


def _build_transaction(header: _Header, cells: list[str], imported_at: dt.datetime) -> Transaction:
    if any(cell.strip() for cell in cells[header.width :]):
        raise ValidationError("unexpected non-empty cells beyond the header")
    values: dict[str, str] = {}
    for col, position in header.index.items():
        if position >= len(cells):
            raise ValidationError("not enough fields")
        values[col] = cells[position]
    date, amount, description = header.format.parse(values)
    return Transaction(date=date, amount=amount, description=description, imported_at=imported_at)


def _record_error(errors: list[RowError], line_no: int, message: str, strict: bool) -> None:
    if strict:
        raise StatementRowError(message, line_no=line_no)
    errors.append(RowError(line_no=line_no, message=message))


def _dedup_key(tx: Transaction) -> tuple[dt.date, Decimal, str]:
    return (tx.date, tx.amount, normalize_description(tx.description))


def detect_format(path: str | os.PathLike[str]) -> str:
    """Возвращает имя формата выписки: 'nova', 'sfera' или 'sfera_split'. Хранилище не трогает."""
    text, _ = _read_text(path)
    return _detect(text, None).format.name


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    fmt — формат явно; None — определить по заголовку.
    strict=True — на первой ошибочной строке бросает StatementRowError, ничего не записывая.
    strict=False — ошибочные строки попадают в ImportResult.errors, остальные импортируются.
    Дубликаты (по дате, сумме и normalize_description, с учётом количества) не добавляются.
    Запись в store одна на весь импорт.
    """
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _read_text(path)
    header = _detect(text, fmt)

    rows: list[Transaction] = []
    errors: list[RowError] = []
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=header.format.delimiter)
    start = 1  # физическая строка, с которой начинается следующая запись
    header_seen = False
    while True:
        try:
            cells = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            # После ошибки csv позицию не восстанавливаем: разбор останавливается.
            _record_error(errors, start, f"cannot read record: {exc}", strict)
            break
        line_no, start = start, reader.line_num + 1
        if _is_blank(cells):
            continue
        if not header_seen:
            header_seen = True
            continue
        try:
            rows.append(_build_transaction(header, cells, imported_at))
        except ValidationError as exc:
            _record_error(errors, line_no, str(exc), strict)

    known = Counter(_dedup_key(tx) for tx in store.all())
    to_add: list[Transaction] = []
    duplicates = 0
    for tx in rows:
        key = _dedup_key(tx)
        if known[key] > 0:
            known[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = replace(tx, category=category)
        to_add.append(tx)

    if to_add:
        store.add_many(to_add)
    logger.info(
        "imported %d transactions from %s (format %s, duplicates %d, errors %d)",
        len(to_add),
        path,
        header.format.name,
        duplicates,
        len(errors),
    )
    return ImportResult(
        format=header.format.name,
        encoding=encoding,
        added=len(to_add),
        duplicates=duplicates,
        errors=tuple(errors),
    )


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку «Новы» в store и возвращает число добавленных транзакций.

    Обёртка над import_statement(fmt="nova", strict=True): при ошибке строки
    бросает StatementRowError и ничего не записывает.
    """
    return import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    ).added

